const plans=[['Free','₹0','Basic profile · Organic enquiries'],['Starter','₹999/mo','Expanded portfolio · Packages'],['Professional','₹2,499/mo','Lead benefits · Team access'],['Premium','₹4,999/mo','Enhanced promotions · Priority support']];export default function Billing(){return <main className="billing-page"><header className="portfolio-header"><a className="brand" href="/">WedConnect</a><span>Vendor billing</span></header><section className="billing-hero"><p className="eyebrow">Plans and credits</p><h1>Grow at your own pace</h1><p>WedConnect charges for optional tools and lead credits. We do not charge commission on wedding bookings.</p></section><section className="plan-grid">{plans.map(([n,p,f])=><article key={n}><span>{n}</span><h2>{p}</h2><p>{f}</p><button className="secondary" type="button">Choose {n}</button></article>)}</section><section className="billing-note"><strong>Checkout unavailable until configured</strong><p>Razorpay test keys and a webhook secret are required. Credits and subscriptions activate only after a signature-verified captured payment.</p></section></main>}
